<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import DataChart from '@/components/DataChart.vue'
import { getComparisonDetail, getExperiment, getPredictionRecords } from '@/api/ml'
import type { Experiment } from '@/types/ml'
const rows=ref<any[]>([]), selected=ref<Experiment>(), loading=ref(false),formalRanking=ref(false),records=ref<any[]>([]),recordTotal=ref(0),filters=ref({sid:'',min_abs_error:undefined as number|undefined,page:1,page_size:20})
const measured=computed(()=>rows.value.filter(r=>r.mae!=null))
const maeOption=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'category',data:measured.value.map(r=>r.model_type.toUpperCase())},yAxis:{type:'value',name:'MAE (m/s)'},series:[{type:'bar',data:measured.value.map(r=>r.mae),itemStyle:{color:'#397fa5'}}]}))
const rmseOption=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'category',data:measured.value.map(r=>r.model_type.toUpperCase())},yAxis:{type:'value',name:'RMSE (m/s)'},series:[{type:'bar',data:measured.value.map(r=>r.rmse),itemStyle:{color:'#d28745'}}]}))
const comparisonOption=computed(()=>{const p=selected.value?.metrics.test?.points??[];return{tooltip:{trigger:'axis'},legend:{data:['真实风速','预测风速']},xAxis:{type:'category',data:p.map(v=>v.target_time.slice(0,10)),axisLabel:{show:false}},yAxis:{type:'value',name:'m/s'},series:[{name:'真实风速',type:'line',showSymbol:false,data:p.map(v=>v.actual)},{name:'预测风速',type:'line',showSymbol:false,data:p.map(v=>v.predicted)}]}})
const errorOption=computed(()=>{const p=selected.value?.metrics.test?.points??[];const bins=Array.from({length:13},(_,i)=>i-6);return{xAxis:{type:'category',data:bins.map(v=>`${v}~${v+1}`)},yAxis:{type:'value',name:'样本'},series:[{type:'bar',data:bins.map(v=>p.filter(x=>x.error>=v&&x.error<v+1).length)}]}})
async function select(row:any){if(row.experiment_id)selected.value=await getExperiment(row.experiment_id)}
async function loadRecords(){const result=await getPredictionRecords(filters.value);records.value=result.items;recordTotal.value=result.total}
function download(path:string){window.location.href=path}
onMounted(async()=>{loading.value=true;const detail=await getComparisonDetail();rows.value=detail.items;formalRanking.value=detail.formal_ranking_allowed;if(measured.value.length)await select(measured.value[0]);await loadRecords();loading.value=false})
</script>
<template><section v-loading="loading" class="page-stack"><div class="page-heading"><div><h2>预测性能评估</h2><p>独立事件测试集 · 所有指标来自已保存模型</p></div><div class="settings-actions"><el-button @click="download('/api/exports/model-comparison.png')">导出 PNG</el-button><el-button @click="download('/api/exports/workbook')">导出科研工作簿</el-button></div></div><el-alert title="公平比较口径" :description="formalRanking?'测试集未参与训练；当前正式实验的数据版本、质量规则、时效、单位和测试样本完全一致，可进行排名。':'测试集未参与训练；只有数据版本、质量规则、时效、单位和样本标识完全一致的实验才允许正式排名。SAF-Net 尚无正式结果。'" type="info" :closable="false" show-icon/><div class="chart-grid"><el-card shadow="never"><DataChart :option="maeOption" label="模型 MAE 对比"/></el-card><el-card shadow="never"><DataChart :option="rmseOption" label="模型 RMSE 对比"/></el-card></div><el-card shadow="never"><el-table :data="rows" @row-click="select"><el-table-column prop="name" label="实验"/><el-table-column prop="model_type" label="模型"/><el-table-column prop="test_count" label="测试样本"/><el-table-column label="MAE"><template #default="{row}">{{row.mae==null?'尚无正式结果':row.mae.toFixed(3)}}</template></el-table-column><el-table-column label="RMSE"><template #default="{row}">{{row.rmse==null?'—':row.rmse.toFixed(3)}}</template></el-table-column><el-table-column label="Bias"><template #default="{row}">{{row.bias==null?'—':row.bias.toFixed(3)}}</template></el-table-column><el-table-column label="可比较"><template #default="{row}"><el-tag :type="row.comparable?'success':'info'">{{row.comparable?'是':'否'}}</el-tag></template></el-table-column></el-table></el-card><template v-if="selected"><div class="chart-grid"><el-card shadow="never"><DataChart :option="comparisonOption" label="真实与预测风速对比"/></el-card><el-card shadow="never"><DataChart :option="errorOption" label="预测误差分布"/></el-card></div></template><el-card shadow="never"><template #header><div class="card-header"><strong>已保存预测记录</strong><el-button @click="download('/api/exports/predictions.csv')">导出筛选结果 CSV</el-button></div></template><div class="settings-actions"><el-input v-model="filters.sid" clearable placeholder="SID" style="width:180px"/><el-input-number v-model="filters.min_abs_error" :min="0" placeholder="最小绝对误差"/><el-button @click="loadRecords">查询</el-button></div><el-table :data="records"><el-table-column prop="model_name" label="模型"/><el-table-column prop="sid" label="SID" width="130"/><el-table-column prop="forecast_time" label="起报时间" width="190"/><el-table-column prop="predicted_wind" label="预测 m/s"/><el-table-column prop="actual_wind" label="真实 m/s"/><el-table-column prop="absolute_error" label="绝对误差"/></el-table><el-pagination class="pagination" v-model:current-page="filters.page" :page-size="filters.page_size" :total="recordTotal" @current-change="loadRecords"/></el-card></section></template>
<style scoped>.page-stack > .el-alert{display:none}</style>
